// quaternion functions
vec4 invQuat=vec4(1, 1, 1, -1);
vec4 getQuat(vec3 ax, float a){
  return vec4(normalize(ax)*sin(a*.5), cos(a*.5));
}
vec4 getQuat(vec3 curDir, vec3 trgtDir){
  curDir=normalize(curDir);
  trgtDir=normalize(trgtDir);
  vec3 ax=cross(trgtDir, curDir);
  float a=acos(dot(curDir, trgtDir));
  return getQuat(ax, a);
}
vec4 mulQuat(vec4 q1, vec4 q2){
  vec3 ax=q1.w*q2.xyz+q2.w*q1.xyz+cross(q1.xyz, q2.xyz);
  float a=q1.w*q2.w-dot(q1.xyz, q2.xyz);
  return vec4(ax, a);
}
void pRotQuat(inout vec3 p, vec4 quat){
  p=p+2.*cross(quat.xyz, cross(quat.xyz, p)-quat.w*p);
}

void perspectiveCam(vec2 uv){
  vec3 up=vec3(0, 1, 0);
  vec3 dir=vec3(0, 0, -1);
  pRotQuat(up, cam0.quaternion);
  pRotQuat(dir, cam0.quaternion);
  up=up.xzy, dir=dir.xzy;
  vec3 pos=cam0.position;
  float fov=cam0.fov;
  vec3 target=pos-dir;
  vec3 cw=normalize(target-pos);
  vec3 cu=normalize(cross(cw, up));
  vec3 cv=normalize(cross(cu, cw));
  cam0.up=up;
  mat3 camMat=mat3(cu, cv, cw);
  ray.origin=pos;
  ray.direction=normalize(camMat*normalize(vec3(sin(fov)*uv.x, sin(fov)*uv.y, -cos(fov))));
}

void camera(vec2 uv){
  perspectiveCam(uv);
}



// SDF functions
// ---------------------------------------------------------------------
float sdSphere(vec3 p, float r){
  return length(p)-r;
}

float sdPlane(vec3 p){
  return p.y;
}

float sdBox(vec3 p, vec3 b){
  p=abs(p)-b;
  return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

float sdEllipsoid(vec3 p, vec3 r){
  float k0=length(p/r);
  float k1=length(p/(r*r));
  return k0*(k0-1.)/k1;
}

float sdTorus(vec3 p, vec2 t){
  vec2 q=vec2(length(p.xz)-t.x, p.y);
  return length(q)-t.y;
}

float sdCappedTorus(vec3 p, vec2 r, float per){
  p.x=abs(p.x);
  vec2 sc=vec2(sin(per), cos(per));
  float k=(sc.y*p.x>sc.x*p.z) ? dot(p.xz, sc) : length(p.xz);
  return sqrt(dot(p, p)+r.x*r.x-2.*r.x*k)-r.y;
}

float sdCappedCylinder(vec3 p, vec2 h){
  vec2 d=abs(vec2(length(p.xz), p.y))-h;
  return ((min(max(d.x, d.y), 0.)+length(max(d, 0.))));
}

float sdPieCylinder(vec3 p, float r, float h, float per){
  per=mod(per, PI);
  vec2 c=vec2(sin(per), cos(per));
  p.xz=c.y*p.xz+c.x*vec2(p.z, -p.x);// rotation
  p.x=abs(p.x);
  float l=length(p.xz)-r;
  float m=length(p.xz-c*clamp(dot(p.xz, c), 0., r));
  float x=max(l, m*sign(c.y*p.x-c.x*p.z));
  float y=abs(p.y)-h;
  return ((min(max(x, y), 0.)+length(max(vec2(x, y), 0.))));
}

vec4 bUni(vec4 a, vec4 b){
  return a.w<b.w ? a : b;
}

float bUniS(float a, float b, float r){
  r*=1.35;
  float h=max(r-abs(a-b), 0.)/r;
  return min(a, b)-h*h*h*r*(1./6.);
}

bool POW = false;

vec3 pow_mix(vec3 colA, vec3 colB, float h){
  float baseg = 36.;
  float f = pow(sabs(h-.5,.5)*2.,.1);
  vec3 gamma=(vec3(baseg)-f*(baseg-.5))*2.;
  colA=pow(colA, 1./gamma);
  colB=pow(colB, 1./gamma);
  return pow(mix(colA, colB, h), gamma*f);
}

vec4 bUniS(vec4 a, vec4 b, float r){
  //float h=clamp(.5+.5*(b.w-a.w)/r, 0., 1.);
  float h=smoothstep(0., 1., .5+.5*(b.w-a.w)/r);
  float d=mix(b.w, a.w, h)-r*h*(1.-h);
  d+=pow(texture(iChannel1,vec2(b.w,a.w)*.5).r,2.2)*.00125;

  // return h > .5 ? a : b; //no blending
  // return vec4((h > .5 ? a : b).rgb, d); //no material blending

  if(POW)
      return vec4(pow_mix(b.rgb, a.rgb, h), d);
  else
      return vec4(mix(b.rgb, a.rgb, h), d);

}

vec4 bSub(vec4 a, vec4 b){
  return (max(-a.w, b.w) == -a.w) ? vec4(a.rgb, -a.w) : b;
}

