  sdBox00_p.xyz+=vec3(-2.032438, -2.685711, -.328315);
  pRot(sdBox00_p, vec3(0));
  d=sdBox(sdBox00_p, vec3(.902973, .902973, .902973)-.06)-.06;
  vec3 sdBox00_001_p=p;

  sdBox00_001_p.xyz+=vec3(-2.00575, -2.971098, -.345337);
  pRot(sdBox00_001_p, vec3(0));
  d=bUniS(sdBox(sdBox00_001_p, vec3(.902973, .902973, .902973)-.06)-.06, d, .01);
  res=bUniS(vec4(MAT_ERNST0_007_COL, d), res, .01);

  vec3 sdCappedCylinder00_p=p;
  sdCappedCylinder00_p.xyz+=vec3(.531891, -2.506936, .5409);
  pRot(sdCappedCylinder00_p, vec3(0));
  d=sdCappedCylinder(sdCappedCylinder00_p, vec2(.953907, 1.785845)-.09)-.09;
  res=bUniS(vec4(MAT_ERNST0_003_COL, d), res, .82);

  vec3 sdCappedTorus00_p=p;
  sdCappedTorus00_p.xyz+=vec3(-.119818, -4.095171, .279885);
  pRot(sdCappedTorus00_p, vec3(1.570796, 0., 0.));
  d=sdCappedTorus(sdCappedTorus00_p, vec2(1., .5), 1.843616);
  res=bUniS(vec4(MAT_ERNST0_004_COL, d), res, .4);

  vec3 sdEllipsoid00_p=p;
  sdEllipsoid00_p.xyz+=vec3(-2.617105, -4.36887, .95226);
  pRot(sdEllipsoid00_p, vec3(0));
  d=sdEllipsoid(sdEllipsoid00_p, vec3(1.215524, 1.296544, 1.));
  res=bUniS(vec4(MAT_ERNST0_005_COL, d), res, .7);

  vec3 sdPlane00_p=p;
  sdPlane00_p.xyz+=vec3(0);
  pRot(sdPlane00_p, vec3(0));
  d=sdPlane(sdPlane00_p);
  res=bUniS(vec4(MAT_ERNST0_002_COL, d), res, .52);

  vec3 sdSphere00_p=p;
  sdSphere00_p.xyz+=vec3(.14608, -1.906251, -.993266);
  d=sdSphere(sdSphere00_p, .832277);
  res=bUniS(vec4(MAT_ERNST0_001_COL, d), res, .649);

  vec3 sdTorus00_p=p;
  sdTorus00_p.xyz+=vec3(-1.971172, -1.301637, -.489569);
  pRot(sdTorus00_p, vec3(0));
  d=sdTorus(sdTorus00_p, vec2(1., .71));
  res=bUniS(vec4(MAT_ERNST0_006_COL, d), res, .574);

  vec3 sdPieCylinder00_p=p;
  sdPieCylinder00_p.xyz+=vec3(-2.968206, -.845974, .017411);
  pRot(sdPieCylinder00_p, vec3(0));
  d=sdPieCylinder(sdPieCylinder00_p, .832876, .832876, 3.141278);
  res=bUniS(vec4(MAT_ERNST0_008_COL, d), res, .01);

  vec3 sdSphere04_p=p;
  sdSphere04_p.xyz+=vec3(2.51909, -3.234557, .002026);
  d=sdSphere(sdSphere04_p, .612911);
  res=bUniS(vec4(MAT_ERNST0_013_COL, d), res, .791047);

